import ast
# 1. Syntax Check: Must use IfExp (ternaries)
tree = ast.parse(code)
ternaries = [n for n in ast.walk(tree) if isinstance(n, ast.IfExp)]
if len(ternaries) < 4:
    raise AssertionError(f'You must use the one-line ternary format for all 4 steps. Found {len(ternaries)}.')

# 2. Logic Check: Multi-scenario testing
test_cases = [
    {'temp': 35, 'age': 16, 'err': 0, 'cart': 3, 'exp_w': 'Hot', 'exp_a': 'Minor', 'exp_s': 'All systems normal', 'exp_p': 45},
    {'temp': 20, 'age': 25, 'err': 404, 'cart': 0, 'exp_w': 'Pleasant', 'exp_a': 'Adult', 'exp_s': 'Error detected', 'exp_p': 0}
]

for case in test_cases:
    t_code = code.replace('temperature = 35', f'temperature = {case["temp"]}')
    t_code = t_code.replace('age = 16', f'age = {case["age"]}')
    t_code = t_code.replace('error_code = 0', f'error_code = {case["err"]}')
    t_code = t_code.replace('items_in_cart = 3', f'items_in_cart = {case["cart"]}')

    env = {}
    exec(t_code, {}, env)

    if env.get('weather_status') != case['exp_w']:
        raise AssertionError(f'Weather logic failed for {case["temp"]}°C')
    if env.get('age_category') != case['exp_a']:
        raise AssertionError(f'Age category logic failed for age {case["age"]}')
    if env.get('system_status') != case['exp_s']:
        raise AssertionError(f'System status logic failed for error code {case["err"]}')
    if env.get('total_price') != case['exp_p']:
        raise AssertionError(f'Total price logic failed for {case["cart"]} items')

print('TEST_PASSED: All ternary expressions are logically sound!')
